target.css:
:root {
  --cream: #f7f0e3;
  --parchment: #ede0c8;
  --bark: #7a5230;
  --bark-dark: #4e321a;
  --wheat: #c9a96e;
  --rust: #b84e1a;
  --sage: #5a7a52;
  --sage-light: #d6e8d3;
  --amber: #e8a830;
  --amber-light: #fdf4dc;
  --ink: #2c1f0e;
  --muted: #9a8068;
  --white: #ffffff;
  --row-alt: #f2e8d8;
}

article.starter-log {
  background-color: var(--cream);
  border: 2px solid var(--bark);
  border-radius: 8px;
  width: 460px;
  overflow: hidden;
  font-size: 13px;
  color: var(--ink);
}

.log-header {
  background-color: var(--bark);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 14px;
}

.log-badge {
  font-size: 24px;
  line-height: 1;
  flex-shrink: 0;
}

.log-title {
  flex: 1;
}

.log-title h1 {
  font-size: 15px;
  font-weight: 700;
  color: var(--cream);
  margin: 0;
  line-height: 1.2;
  letter-spacing: 0.3px;
}

.log-subtitle {
  font-size: 10px;
  color: var(--parchment);
  margin: 1px 0 0;
  font-style: italic;
  opacity: 0.85;
}

.log-day {
  display: flex;
  flex-direction: column;
  align-items: center;
  background-color: var(--bark-dark);
  border-radius: 5px;
  padding: 4px 9px;
  font-size: 9px;
  font-weight: 600;
  color: var(--wheat);
  letter-spacing: 1px;
  text-transform: uppercase;
  line-height: 1;
  gap: 1px;
}

.log-day span {
  font-size: 19px;
  font-weight: 700;
  color: var(--amber);
  line-height: 1;
}

.log-body {
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.strain-row {
  display: flex;
  background-color: var(--parchment);
  border: 1px solid var(--wheat);
  border-radius: 5px;
  overflow: hidden;
}

.strain-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 8px;
  border-right: 1px solid var(--wheat);
  gap: 2px;
}

.strain-info:last-child {
  border-right: none;
}

.strain-label {
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--muted);
}

.strain-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--bark-dark);
}

.strain-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--rust);
}

.feed-grid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  border: 1px solid var(--wheat);
  border-radius: 5px;
  overflow: hidden;
}

.feed-cell {
  padding: 5px 8px;
  font-size: 12px;
  text-align: center;
  color: var(--ink);
  border-bottom: 1px solid var(--parchment);
  background-color: var(--cream);
  display: flex;
  align-items: center;
  justify-content: center;
}

.feed-cell:nth-child(8n+5),
.feed-cell:nth-child(8n+6),
.feed-cell:nth-child(8n+7),
.feed-cell:nth-child(8n+8) {
  background-color: var(--row-alt);
}

.feed-cell.head {
  background-color: var(--bark-dark);
  color: var(--parchment);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  border-bottom: none;
}

.rise {
  font-size: 11px;
  font-weight: 700;
  border-radius: 10px;
  padding: 2px 6px;
}

.rise.good {
  background-color: var(--sage-light);
  color: var(--sage);
}

.rise.ok {
  background-color: var(--amber-light);
  color: var(--amber);
}

.log-footer {
  display: flex;
  align-items: center;
  gap: 10px;
  background-color: var(--parchment);
  border-top: 2px solid var(--wheat);
  padding: 8px 14px;
}

.note-block {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.note-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--muted);
}

.note-text {
  font-size: 11px;
  color: var(--bark-dark);
  font-style: italic;
  line-height: 1.3;
}

.log-status {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  border-radius: 10px;
  padding: 4px 11px;
  flex-shrink: 0;
}

.log-status.active {
  background-color: var(--sage);
  color: var(--white);
}
